answer:
1. Inside Class Definition:
- Defined directly within class declaration.
- Treated automatically as inline function by compiler.
Example:
class Box {
public:
    int length;
    int getVolume(int h, int w) { return length * h * w; }
};

2. Outside Class Definition:
- Declared (prototyped) inside class and defined outside using Scope Resolution Operator (::).
Example:
class Box {
public:
    int length;
    int getVolume(int h, int w);
};
int Box::getVolume(int h, int w) {
    return length * h * w;
}

Objects can be passed to functions in two ways:
1. Pass by Value: Copy of entire object passed.
2. Pass by Reference: Address of object passed.

Working Program to add two Time objects:
#include <iostream>
using namespace std;
class Time {
public:
    int hours, minutes;
    void set(int h, int m) { hours = h; minutes = m; }
    void add(Time t1, Time t2) { // Passing objects by value
        minutes = t1.minutes + t2.minutes;
        hours = t1.hours + t2.hours + (minutes / 60);
        minutes %= 60;
    }
    void display() { cout << hours << " hrs : " << minutes << " mins\n"; }
};
int main() {
    Time t1, t2, t3;
    t1.set(2, 45); t2.set(1, 30);
    t3.add(t1, t2);
    cout << "Total Time: "; t3.display();
    return 0;
}

